 [RuntimeInitializeOnLoadMethod]static void Boot(){bool run=Array.IndexOf(Environment.GetCommandLineArgs(),"-tsBowlingRebound")>=0;
#if UNITY_EDITOR
 run|=UnityEditor.SessionState.GetBool("LWS.BowlingRebound",false);UnityEditor.SessionState.SetBool("LWS.BowlingRebound",false);
#endif
 if(run){var g=new GameObject("Bowling equivalent physical-delivery comparison");DontDestroyOnLoad(g);if(FindAnyObjectByType<SportsProbeInputIsolation>()==null)g.AddComponent<SportsProbeInputIsolation>();g.AddComponent<BowlingReboundProbe>();}}
 string folder;int errors;public int SecondaryContacts;public readonly bool[] returned=new bool[10];readonly StringBuilder report=new StringBuilder();void Check(bool yes,string label){report.AppendLine((yes?"PASS ":"FAIL ")+label);if(!yes)errors++;Write();}void Write(){File.WriteAllText(folder+"/progress.txt",report.ToString());}void Error(string message,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception){errors++;report.AppendLine("ERROR "+message+"\n"+stack);Write();}}
 IEnumerator Start(){bool baseline=false;
#if UNITY_EDITOR
 baseline=UnityEditor.SessionState.GetBool("LWS.BowlingReboundBaseline",false);
#endif
 folder=SportsEvidencePaths.Folder(baseline?"BowlingReboundBefore":"BowlingReboundAfter");File.WriteAllText(folder+"/result.txt","RUNNING "+DateTime.UtcNow.ToString("O"));Application.logMessageReceived+=Error;yield return SportsProbeScene.Ensure<BowlingMatch>("TruckBowling");var m=FindAnyObjectByType<BowlingMatch>();yield return null;var lane=m.lanes[0];foreach(var p in lane.pins){var tracker=p.gameObject.AddComponent<BowlingReboundContactProbe>();tracker.probe=this;tracker.pin=p;}int meaningful=0,chains=0,total=0,strikes=0,imperfect=0;float largestSpeed=0;report.AppendLine("Initialized physical truck fixtures, same15 lateral/speed inputs repeated twice. No score or pinfall injection. baseline="+baseline);
 for(int repeat=0;repeat<2;repeat++)foreach(float speed in new[]{12f,15f,17f})foreach(float x in new[]{-.75f,-.35f,0,.35f,.75f}){m.ChangeSetup();UnityEngine.Random.InitState(1801+repeat);m.PresetAI(1,BowlingMode.Simultaneous);foreach(var l in m.lanes)l.ai.enabled=false;Check(m.StartMatch(),"fixture starts "+repeat+" / "+speed+" / "+x);Time.timeScale=6;yield return new WaitForSeconds(.3f);int locks=lane.ScoreLocks;SecondaryContacts=0;Array.Clear(returned,0,10);var maxZ=new float[10];for(int i=0;i<10;i++)maxZ[i]=lane.pins[i].body.position.z;var truck=lane.truck;var position=new Vector3(lane.center+x,.28f,lane.pinLine-8);truck.body.position=position;truck.body.rotation=Quaternion.identity;truck.transform.SetPositionAndRotation(position,Quaternion.identity);truck.body.linearVelocity=Vector3.forward*speed;truck.body.angularVelocity=Vector3.zero;truck.Control(Vector2.zero);Physics.SyncTransforms();float end=Time.realtimeSinceStartup+25,peak=0;bool early=false;while(lane.ScoreLocks==locks&&Time.realtimeSinceStartup<end){for(int i=0;i<10;i++){var p=lane.pins[i];maxZ[i]=Mathf.Max(maxZ[i],p.body.position.z);if(maxZ[i]>lane.pinLine+4.5f&&p.body.position.z<lane.pinLine+3&&p.body.linearVelocity.z<-.6f)returned[i]=true;peak=Mathf.Max(peak,p.body.linearVelocity.magnitude);if(lane.Phase==BowlingPhase.Settling&&p.body.linearVelocity.magnitude>1&&lane.sweep.position.y<lane.sweepRaisedY-.05f)early=true;}yield return null;}int count=0;foreach(bool r in returned)if(r)count++;Check(lane.ScoreLocks==locks+1,"physical delivery settles and locks once");Check(!early,"sweeper remains overhead throughout live pin action");if(lane.LastPins>0)Check(lane.LegalPinContact,"actual truck-to-pin provenance");meaningful+=count;chains+=SecondaryContacts;total+=lane.LastPins;if(lane.LastPins==10)strikes++;else imperfect++;largestSpeed=Mathf.Max(largestSpeed,peak);report.AppendLine("DELIVERY repeat="+repeat+" speed="+speed+" x="+x+" pins="+lane.LastPins+" returns="+count+" secondaryContacts="+SecondaryContacts+" peakPinSpeed="+peak.ToString("F2")+" result="+lane.Result.Replace('\n',' '));Write();}
 m.ChangeSetup();report.AppendLine("MEASURE deliveries=30 pins="+total+" strikes="+strikes+" imperfect="+imperfect+" meaningfulReturns="+meaningful+" secondaryContacts="+chains+" peakPinSpeed="+largestSpeed.ToString("F2"));report.AppendLine("ERRORS="+errors+". Equivalent seeded physical deliveries, not human balance proof or hardware/GPU evidence.");File.WriteAllText(folder+"/result.txt",report.ToString());Application.logMessageReceived-=Error;Time.timeScale=1;if(!Application.isEditor)Application.Quit(errors==0?0:2);}
 void OnDestroy(){Application.logMessageReceived-=Error;Time.timeScale=1;}
